package pe.com.dentalamericana.finance;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;@Entity@Table(name="movimientos_caja")public class CashMovement{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="sesion_caja_id",nullable=false)private Long cashSessionId;@Enumerated(EnumType.STRING)@Column(nullable=false)private MovementType tipo;@Column(nullable=false)private String categoria;@Column(nullable=false)private String origen;@Column(name="origen_id",nullable=false)private Long sourceId;@Column(name="metodo_pago_id")private Long paymentMethodId;@Column(nullable=false)private BigDecimal monto;@Column(nullable=false)private String descripcion;@Column(name="creado_por",nullable=false)private Long createdBy;@Column(name="creado_en",nullable=false,updatable=false)private Instant createdAt;protected CashMovement(){}public CashMovement(Long session,MovementType type,String category,String source,Long sourceId,Long method,BigDecimal amount,String description,Long actor){cashSessionId=session;tipo=type;categoria=category;origen=source;this.sourceId=sourceId;paymentMethodId=method;monto=amount;descripcion=description;createdBy=actor;}@PrePersist void create(){createdAt=Instant.now();}public Long getId(){return id;}public Long getCashSessionId(){return cashSessionId;}public MovementType getType(){return tipo;}public String getCategory(){return categoria;}public String getSource(){return origen;}public Long getSourceId(){return sourceId;}public Long getPaymentMethodId(){return paymentMethodId;}public BigDecimal getAmount(){return monto;}public String getDescription(){return descripcion;}public Instant getCreatedAt(){return createdAt;}}
